{"expression": "// Find the Required checkbox - look for a label with 'Required' text and its associated input
const els = document.querySelectorAll('*');
for (let el of els) {
  if (el.tagName === 'LABEL' && el.textContent.trim() === 'Required') {
    const parent = el.parentElement;
    const checkbox = parent.querySelector('input[type="checkbox"]');
    if (checkbox) {
      console.log('Found Required checkbox, clicking');
      checkbox.click();
      break;
    } else {
      console.log('Label found but no checkbox in parent, parent HTML is: ' + parent.innerHTML.substring(0, 500));
      break;
    }
  }
}
"}

